code_examples.vulnerable:
class UserObj {
    #privArray = [];

    // private 배열에 외부 값을 바로 대입하는 public 메소드를 사용하는 경우 취약
    set_private_member = (input_list) => {
        this.#privArray = input_list;
    }
}

code_examples.safe:
class UserObj2 {
    #privArray = [];

    // 사용자가 전달한 값을 private가 아닌 public 배열로 저장
    set_private_member = (input_list) => {
        this.userInput = input_list;
    }
}
